    // shadow high-water mark of the first-sampled bin's count
    reg [3:0] hi_first;

    initial begin
        bin0       = 4'd0;
        bin1       = 4'd0;
        bin2       = 4'd0;
        bin3       = 4'd0;
        total      = 6'd0;
        first_bin  = 2'd0;
        saw_sample = 1'b0;
        pre_purge  = 1'b1;
        hi_first   = 4'd0;
    end

    wire [3:0] sel_cnt   = (i_sel == 2'd0) ? bin0 :
                           (i_sel == 2'd1) ? bin1 :
                           (i_sel == 2'd2) ? bin2 : bin3;

