        (do_add && saw_sample && (i_sel == first_bin))    ? (first_cnt + 4'd1) :
        (do_rem && saw_sample && (i_sel == first_bin))    ? (first_cnt - 4'd1) :
                                                            first_cnt;

    always @(posedge clk) begin
        if (i_ce) begin
            if (do_add) begin
                total <= total + 6'd1;
                case (i_sel)
