module skid_stage (
    input  wire       clk,
    input  wire       rst,
    input  wire       en,          // idle condition: en low freezes all state
    input  wire       in_valid,
    input  wire [7:0] in_data,
    input  wire       out_ready,
    output wire       in_ready,
    output reg        out_valid,
    output reg  [7:0] out_data
);
    // skid buffer: only meaningful while the stall flag skid_valid is up
    reg        skid_valid;
    reg  [7:0] skid_data;

    // redundant occupancy counter (3 bits wide, but only 0..2 are real)
    reg  [2:0] occ;

    // sticky arm: set the first time a word is actually accepted
    reg        armed;

    initial begin
        out_valid  = 1'b0;
        out_data   = 8'h00;
        skid_valid = 1'b0;
        skid_data  = 8'h00;
        occ        = 3'd0;
        armed      = 1'b0;
    end

    assign in_ready = !skid_valid;

    wire accept = en && in_valid && in_ready;
    wire drain  = en && out_valid && out_ready;

    always @(posedge clk) begin
        if (rst) begin
            out_valid  <= 1'b0;
            out_data   <= 8'h00;
            skid_valid <= 1'b0;
            skid_data  <= 8'h00;
            occ        <= 3'd0;
            armed      <= 1'b0;
        end else if (en) begin
            // output register / skid promotion
            if (!out_valid || out_ready) begin
                if (skid_valid) begin
                    out_data   <= skid_data;
                    out_valid  <= 1'b1;
                    skid_valid <= 1'b0;
                end else if (in_valid) begin
                    out_data  <= in_data;
                    out_valid <= 1'b1;
                end else begin
                    out_valid <= 1'b0;
                end
            end else begin
                // downstream stalled: park the incoming word in the skid slot
                if (in_valid && !skid_valid) begin
                    skid_data  <= in_data;
                    skid_valid <= 1'b1;
                end
            end

            // occupancy bookkeeping, tracked independently of the flags
            occ <= occ + (accept ? 3'd1 : 3'd0) - (drain ? 3'd1 : 3'd0);

            if (accept) armed <= 1'b1;
        end
    end

    // P, part 1: once the stage has ever accepted a word, occupancy never
    // exceeds 2 even though the counter is 3 bits wide
    always @(posedge clk)
        if (armed)
            assert (occ <= 3'd2);

    // P, part 2: once armed, whenever the skid slot holds a meaningful word the
    // stage is occupancy-saturated at exactly 2
    always @(posedge clk)
        if (armed)
            assert (!skid_valid || occ == 3'd2);
endmodule

