module age_matrix_iq (
    input  wire        clk,
    input  wire        i_ce,
    input  wire        i_alloc,
    input  wire        i_alloc_ready,
    input  wire [31:0] i_alloc_tag,
    input  wire        i_issue,
    input  wire [3:0]  i_wake,
    output reg  [31:0] o_issue_tag,
    output wire        o_issue_valid,
    output wire [31:0] o_issue_cnt
);
    // age[i*4+j] == 1 means entry i is older than entry j
    reg [3:0]   valid = 4'b0000;
    reg [3:0]   ready = 4'b0000;
    reg [15:0]  age = 16'h0000;
    reg [127:0] tags = 128'd0;
    reg [31:0]  issue_cnt = 32'd0;
    reg         armed = 1'b0;
    reg         pv = 1'b0;

    reg [3:0] grant;
    reg [3:0] free_sel;
    integer i, j, k;

    wire [3:0] rv = valid & ready;
    wire issue_fire = i_ce & i_issue & (|rv);
    wire alloc_fire = i_ce & i_alloc & ~(&valid);

    // oldest-ready select: an entry wins if no other ready entry is older
    always @(*) begin
        for (i = 0; i < 4; i = i + 1) begin
            grant[i] = rv[i];
            for (j = 0; j < 4; j = j + 1)
                if (j != i && rv[j] && age[j*4+i]) grant[i] = 1'b0;
        end
        if (!valid[0])      free_sel = 4'b0001;
        else if (!valid[1]) free_sel = 4'b0010;
        else if (!valid[2]) free_sel = 4'b0100;
        else if (!valid[3]) free_sel = 4'b1000;
        else                free_sel = 4'b0000;
        o_issue_tag = 32'd0;
        for (k = 0; k < 4; k = k + 1)
            if (grant[k]) o_issue_tag = o_issue_tag | tags[k*32 +: 32];
    end

    assign o_issue_valid = issue_fire;
    assign o_issue_cnt = issue_cnt;

    always @(posedge clk) begin
        if (issue_fire) begin
            issue_cnt <= issue_cnt + 32'd1;
            armed <= 1'b1;
        end
        for (i = 0; i < 4; i = i + 1) begin
            if (alloc_fire && free_sel[i]) begin
                valid[i] <= 1'b1;
                ready[i] <= i_alloc_ready;
                tags[i*32 +: 32] <= i_alloc_tag;
                for (j = 0; j < 4; j = j + 1)
                    if (j != i) begin
                        age[i*4+j] <= 1'b0;
                        age[j*4+i] <= valid[j];
                    end
            end else begin
                if (issue_fire && grant[i]) valid[i] <= 1'b0;
                if (i_ce && valid[i] && i_wake[i]) ready[i] <= 1'b1;
            end
        end
    end

    always @(posedge clk) pv <= 1'b1;

    // after the first issue: if the valid set did not change, no issue was counted
    always @(posedge clk)
        if (pv && armed && $stable(valid))
            assert ($stable(issue_cnt));
endmodule


