module sd_dac_lockstep (
    input wire clk,
    input wire ce,
    input wire mute,
    input wire [15:0] din,
    output reg dout,
    output reg dchk
);
    // main first-order sigma-delta error accumulator
    reg [15:0] acc = 16'h0000;
    // lockstep reference accumulator (does not see mute)
    reg [15:0] acc_chk = 16'h0000;
    // scope register: high until the first mute event
    reg before_mute = 1'b1;
    reg pv = 1'b0;

    initial dout = 1'b0;
    initial dchk = 1'b0;

    wire [16:0] sum     = {1'b0, acc}     + {1'b0, din};
    wire [16:0] sum_chk = {1'b0, acc_chk} + {1'b0, din};

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (mute) begin
            acc  <= 16'h0000;
            dout <= 1'b0;
        end else if (ce) begin
            acc  <= sum[15:0];
            dout <= sum[16];
        end
    end

    always @(posedge clk) begin
        if (ce) begin
            acc_chk <= sum_chk[15:0];
            dchk    <= sum_chk[16];
        end
    end

    always @(posedge clk) begin
        if (mute)
            before_mute <= 1'b0;
    end

    // Absence, before first mute: never (reference bit held) and (main bit toggled)
    always @(posedge clk)
        if (pv && before_mute)
            assert (!($stable(dchk) && !$stable(dout)));
endmodule

